import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.QOeHXaRf.js";const r="/geonetwork-ui/main/docs/assets/flag-category.CI4XaYgv.png",g=JSON.parse('{"title":"Metadata Editor","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"apps/editor.md","filePath":"apps/editor.md"}'),s={name:"apps/editor.md"};function n(d,e,l,h,u,c){return t(),o("div",null,e[0]||(e[0]=[i('<h1 id="metadata-editor" tabindex="-1">Metadata Editor <a class="header-anchor" href="#metadata-editor" aria-label="Permalink to &quot;Metadata Editor&quot;">​</a></h1><p>The <strong>Metadata Editor</strong> application offers a user-friendly interface to create, edit, and publish metadata records.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>A dashboard showing the records available on the platform as well as searching and sorting</li><li>A metadata edition interface allowing the modification of various parts of a record (title, abstract, keywords, dates...)</li><li>Create, duplicate and delete records</li><li>Import remote records using a URL</li><li>Keep a draft while editing a record, with the ability to rollback to the published version and discard changes</li><li>A simplified &quot;light&quot; edition page, used by other applications (e.g. the Datahub for reuses) to let users edit a record without the full editor interface</li></ul><h2 id="run-deploy" tabindex="-1">Run &amp; deploy <a class="header-anchor" href="#run-deploy" aria-label="Permalink to &quot;Run &amp; deploy&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>GeoNetwork version 4.2.5 or above is required for the Metadata Editor app to function normally.</p></div><p>The Metadata Editor application is available as a docker image or as a ZIP archive.</p><h3 id="using-docker" tabindex="-1">Using docker <a class="header-anchor" href="#using-docker" aria-label="Permalink to &quot;Using docker&quot;">​</a></h3><p>The docker image is <code>geonetwork/geonetwork-ui-metadata-editor</code>.</p><p>See the <a href="./../guide/run.html#with-docker">run guide</a> for more information.</p><h3 id="using-the-zip-archive" tabindex="-1">Using the ZIP archive <a class="header-anchor" href="#using-the-zip-archive" aria-label="Permalink to &quot;Using the ZIP archive&quot;">​</a></h3><p>A <code>metadata-editor-VERSION.zip</code> archive is available on every GeoNetwork-UI release: <a href="https://github.com/geonetwork/geonetwork-ui/releases" target="_blank" rel="noreferrer">https://github.com/geonetwork/geonetwork-ui/releases</a></p><p>See the <a href="./../guide/run.html#from-the-zip-archive">run guide</a> for more information.</p><h3 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h3><p>Please refer to the <a href="./../guide/deploy.html">general deploy guide</a> to learn how to deploy GeoNetwork-UI applications.</p><h2 id="supported-metadata-schemas" tabindex="-1">Supported metadata schemas <a class="header-anchor" href="#supported-metadata-schemas" aria-label="Permalink to &quot;Supported metadata schemas&quot;">​</a></h2><p>The editor currently support the following schemas:</p><ul><li>ISO 19139</li><li>ISO 19115-3</li><li>DCAT-AP <em>(support for writing values in a record is limited for now)</em></li></ul><p>Any record written in one of those schemas can be opened and modified in the edition interface.</p><p>When a record is created it uses the preferred schema, currently ISO 19115-3.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The Metadata Editor relies on the GeoNetwork CRUD (create/read/update/delete) API for manipulating records. The records XML is read and modified fully in the browser to allow for a reactive experience as well as offering more possibilities for supported schemas.</p><h3 id="needed-permissions" tabindex="-1">Needed permissions <a class="header-anchor" href="#needed-permissions" aria-label="Permalink to &quot;Needed permissions&quot;">​</a></h3><p>To view and edit records in the Metadata Editor, a user needs to have EDITOR rights on the group where the records are created.</p><p>The REVIEWER rights are also needed for the publication step.</p><ul><li>EDITOR</li><li>REVIEWER</li></ul><h2 id="light-edition-page" tabindex="-1">Light edition page <a class="header-anchor" href="#light-edition-page" aria-label="Permalink to &quot;Light edition page&quot;">​</a></h2><p>Opening <code>/light-edit/{uuid}</code> shows a simplified edition page for the given record, without the dashboard sidebar or page navigation. It is used by the Datahub to edit reuse records, but any application can link to it.</p><p>The top bar offers a &quot;leave&quot; button and a &quot;save&quot; button; there is no draft handling and no separate publication step on this page.</p><h3 id="url-parameters" tabindex="-1">URL parameters <a class="header-anchor" href="#url-parameters" aria-label="Permalink to &quot;URL parameters&quot;">​</a></h3><ul><li><code>redirect_on_leave</code> (optional): a URL-encoded absolute <code>http(s)</code> URL the user is sent back to when clicking the &quot;leave&quot; button. The calling application is responsible for building the complete URL, including the record&#39;s UUID if it wants the user to come back to the record&#39;s page (e.g. <code>/light-edit/{uuid}?redirect_on_leave=https%3A%2F%2Fexample.com%2Fdatahub%2Freuse%2F{uuid}</code>). When the parameter is absent or invalid, the &quot;leave&quot; button is not displayed.</li></ul><h2 id="marking-a-dataset-as-reference-dataset" tabindex="-1">Marking a Dataset as &quot;Reference Dataset&quot; <a class="header-anchor" href="#marking-a-dataset-as-reference-dataset" aria-label="Permalink to &quot;Marking a Dataset as &quot;Reference Dataset&quot;&quot;">​</a></h2><p>For users with administrator privileges, an additional toggle is visible when editing a Dataset Record. This toggle allows the user to mark the Dataset as a &quot;Reference Dataset&quot;, thus pushing forward in search results and offering additional features for it.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisite</p><p>The &quot;Is Reference Dataset&quot; information is stored in the form of what is called a &quot;record flag&quot;. For this feature to work, every record flag should be created in the form of a Category on the GeoNetwork administration UI.</p><p>For this specific toggle, the category to use must be called &quot;geonetwork-ui-flag:IS_REFERENCE_DATASET&quot;. The flag name is case-sensitive and must be exactly as specified here.</p><p>This is done on this url: <code>/geonetwork/srv/eng/admin.console#/classification/categories</code>, and it should look like this: <img src="'+r+'" alt="&quot;Reference Datasets&quot; category"></p></div><h2 id="multilingual-support" tabindex="-1">Multilingual support <a class="header-anchor" href="#multilingual-support" aria-label="Permalink to &quot;Multilingual support&quot;">​</a></h2><blockquote><p>Still under development</p></blockquote><h2 id="concurrent-edition" tabindex="-1">Concurrent edition <a class="header-anchor" href="#concurrent-edition" aria-label="Permalink to &quot;Concurrent edition&quot;">​</a></h2><blockquote><p>Still under development</p></blockquote><h2 id="configuring-the-edition-interface" tabindex="-1">Configuring the edition interface <a class="header-anchor" href="#configuring-the-edition-interface" aria-label="Permalink to &quot;Configuring the edition interface&quot;">​</a></h2><blockquote><p>Still under development</p></blockquote>',40)]))}const m=a(s,[["render",n]]);export{g as __pageData,m as default};
